import { Component, effect, inject, input, output, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';

import { ApiService } from '../shared/api.service';
import { ManufacturerDto } from '../shared/dto';
import { PopupComponent } from '../shared/popup.component';
import { MessageService, errorText } from '../widget/message/message.service';

/** EditManufacturerPresenter/View: popup to create or edit a manufacturer. */
@Component({
  selector: 'app-edit-manufacturer',
  standalone: true,
  imports: [FormsModule, PopupComponent],
  template: `
    <app-popup (autoHide)="onCancel()">
      <div id="gwt-debug-manufacturer-editor" class="editor">
        <div class="row">
          <label for="gwt-debug-manufacturer-input">Name:</label>
          <input
            type="text"
            id="gwt-debug-manufacturer-input"
            [ngModel]="name()"
            (ngModelChange)="name.set($event)"
            (keydown.enter)="onSave()"
          />
        </div>
        <div class="row buttons">
          <button type="button" id="gwt-debug-manufacturer-save" [disabled]="saving()" (click)="onSave()">Save</button>
          <button type="button" id="gwt-debug-manufacturer-close" (click)="onCancel()">Close</button>
        </div>
      </div>
    </app-popup>
  `,
  styles: `
    .row { margin: 5px 0; }
    label { margin-right: 5px; }
    .buttons button { margin-right: 5px; }
  `,
})
export class EditManufacturerComponent {
  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  /** The manufacturer being edited; a new (unsaved) one when creating. */
  readonly manufacturer = input.required<ManufacturerDto>();
  readonly saved = output<ManufacturerDto>();
  readonly closed = output<void>();

  protected readonly name = signal('');
  protected readonly saving = signal(false);

  constructor() {
    // Editor driver: load the bean's properties into the fields.
    effect(() => this.name.set(this.manufacturer().name ?? ''), { allowSignalWrites: true });
  }

  protected onSave(): void {
    if (this.saving()) {
      return;
    }
    // Editor driver flush: the edited copy of the bean.
    const dto: ManufacturerDto = { ...this.manufacturer(), name: this.name() };
    this.saving.set(true);
    this.api.saveOrCreateManufacturer(dto).subscribe({
      next: (savedManufacturer) => {
        this.saving.set(false);
        this.messages.success('Manufacturer saved');
        this.saved.emit(savedManufacturer);
      },
      error: (err) => {
        this.saving.set(false);
        this.messages.error(errorText('Error saving the manufacturer', err));
      },
    });
  }

  protected onCancel(): void {
    this.closed.emit();
  }
}
