import { Component, OnInit, inject, signal } from '@angular/core';

import { ApiService } from '../shared/api.service';
import { ManufacturerDto, formatNumber } from '../shared/dto';
import { MessageService, errorText } from '../widget/message/message.service';
import { EditManufacturerComponent } from './edit-manufacturer.component';

/** ManufacturerPresenter/View: the manufacturer table with Edit and Delete per row. */
@Component({
  selector: 'app-manufacturer',
  standalone: true,
  imports: [EditManufacturerComponent],
  template: `
    <div class="bigTitle">
      <h2><span>Manufacturers</span></h2>
      <div>
        <button type="button" class="addAction" id="gwt-debug-create-manufacturer" (click)="onCreate()">Create</button>
      </div>
      <span class="clear"></span>
    </div>
    <div class="tableWrapper">
      <table class="cellTable" id="gwt-debug-manufacturers" width="100%">
        <colgroup>
          <col style="width: 50px" />
          <col />
          <col style="width: 75px" />
          <col style="width: 75px" />
        </colgroup>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Edit</th>
            <th>Delete</th>
          </tr>
        </thead>
        <tbody>
          @for (manufacturer of manufacturers(); track manufacturer) {
            <tr>
              <td>{{ formatNumber(manufacturer.id) }}</td>
              <td>{{ manufacturer.name }}</td>
              <td><button type="button" (click)="onEdit(manufacturer)">Edit</button></td>
              <td><button type="button" (click)="onDeleteClicked(manufacturer)">Delete</button></td>
            </tr>
          }
        </tbody>
      </table>
    </div>
    @if (editorBean(); as bean) {
      <app-edit-manufacturer [manufacturer]="bean" (saved)="onManufacturerAdded($event)" (closed)="hideEditor()" />
    }
  `,
  styleUrl: '../shared/page.css',
})
export class ManufacturerComponent implements OnInit {
  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  protected readonly formatNumber = formatNumber;
  protected readonly manufacturers = signal<ManufacturerDto[]>([]);
  /** Bean shown in the popup editor; null when the popup is hidden. */
  protected readonly editorBean = signal<ManufacturerDto | null>(null);
  private editingManufacturer: ManufacturerDto | null = null;

  ngOnInit(): void {
    this.api.getManufacturers().subscribe({
      next: (manufacturers) => this.manufacturers.set(manufacturers ?? []),
      error: (err) => this.messages.error(errorText('Error loading the manufacturers', err)),
    });
  }

  protected onCreate(): void {
    this.editingManufacturer = null;
    this.editorBean.set({ name: '', cars: [] });
  }

  protected onEdit(manufacturer: ManufacturerDto): void {
    this.editingManufacturer = manufacturer;
    this.editorBean.set(manufacturer);
  }

  protected hideEditor(): void {
    this.editorBean.set(null);
  }

  protected onDeleteClicked(manufacturer: ManufacturerDto): void {
    if (window.confirm('Are you sure you want to delete ' + manufacturer.name + '?')) {
      this.onDelete(manufacturer);
    }
  }

  private onDelete(manufacturer: ManufacturerDto): void {
    this.api.deleteManufacturer(manufacturer.id as number).subscribe({
      next: () => this.manufacturers.update((list) => list.filter((m) => !sameEntity(m, manufacturer))),
      error: (err) => this.messages.error(errorText('Error deleting the manufacturer', err)),
    });
  }

  protected onManufacturerAdded(saved: ManufacturerDto): void {
    const editing = this.editingManufacturer;
    this.manufacturers.update((list) => {
      const index = editing ? list.findIndex((m) => sameEntity(m, editing)) : -1;
      if (index >= 0) {
        const copy = [...list];
        copy[index] = saved;
        return copy;
      }
      return [...list, saved];
    });
    this.editingManufacturer = saved;
    this.hideEditor();
  }
}

/** BaseEntity.equals(): same id (or same instance when unsaved). */
function sameEntity(a: { id?: number | null }, b: { id?: number | null }): boolean {
  return a === b || (a.id != null && a.id === b.id);
}
