/** JSON bodies of the carstore REST API (see gwt/.../shared/dto). */
export interface ManufacturerDto {
  id?: number | null;
  name: string;
  cars?: CarDto[] | null;
}

export interface CarPropertiesDto {
  id?: number | null;
  someString?: string;
  someNumber?: number;
  someDate?: string;
  car?: CarDto | null;
}

export interface CarDto {
  id?: number | null;
  manufacturer?: ManufacturerDto | null;
  model: string;
  ratings?: RatingDto[] | null;
  carProperties?: CarPropertiesDto | null;
}

export interface RatingDto {
  id?: number | null;
  rating: number | null;
  car: CarDto | null;
}

export interface ManufacturerRatingDto {
  manufacturer: string;
  rating: number | null;
}

/** Same as RatingDto.toString() in the GWT app: "manufacturer/model". */
export function ratingToString(rating: RatingDto): string {
  const car = rating.car;
  if (car && car.manufacturer) {
    return car.manufacturer.name + '/' + car.model;
  }
  return 'Rating ' + (rating.id ?? '');
}

/** Same as GWT NumberCell's default decimal format ("#,##0.###"). */
const decimalFormat = new Intl.NumberFormat('en-US', { maximumFractionDigits: 3 });
export function formatNumber(value: number | null | undefined): string {
  return value === null || value === undefined ? '' : decimalFormat.format(value);
}
