import { HashLocationStrategy } from '@angular/common';
import { Injectable } from '@angular/core';

/**
 * Hash routing with GWT-style history tokens: "#rating" instead of Angular's
 * default "#/rating", so URLs and links match the GWT app's place tokens.
 */
@Injectable()
export class HashTokenLocationStrategy extends HashLocationStrategy {
  override prepareExternalUrl(internal: string): string {
    return super.prepareExternalUrl(internal).replace(/^#\/+/, '#');
  }
}
